-- Undo of content pack 11 (database/content-pack-11-merge-articles.sql). GENERATED by scripts/merge-article-rules.mjs.
-- Moves the examples and exercises back to the rules they came from (the ids were written into metadata by the pack), switches
-- those rules on again and puts the old explanation of "a-or-the" back. New rows of the pack and deleted exact duplicates stay;
-- word links, mistake links, practice attempts, notes and progress stay on "a-or-the".

begin;

update public.rule_examples e set rule_id = r.id
from public.rules r
cross join lateral jsonb_array_elements_text(r.metadata -> 'example_ids') as moved(id)
where r.metadata ->> 'merged_into' = 'a-or-the' and e.id = moved.id::uuid;

update public.rule_exercises e set rule_id = r.id
from public.rules r
cross join lateral jsonb_array_elements_text(r.metadata -> 'exercise_ids') as moved(id)
where r.metadata ->> 'merged_into' = 'a-or-the' and e.id = moved.id::uuid;

update public.rules
set is_active = coalesce((metadata ->> 'was_active')::boolean, true),
    metadata = metadata - 'merged_into' - 'was_active' - 'example_ids' - 'exercise_ids',
    updated_at = now()
where metadata ->> 'merged_into' = 'a-or-the';

update public.rules
set title = 'A or the: new or already known?',
    short_explanation = 'Use a / an when you mention something for the first time or mean any one of its kind. Use the when the listener already knows which one: it was mentioned before, it is clear from the situation, or there is only one.',
    tts_text = 'Use a for something new, and the for something already known.',
    mnemonic = 'A: any one, new. The: that one, we both know it.',
    updated_at = now()
where slug = 'a-or-the';

commit;
